      ogTitle: "Promilleberegner: 4 øl på 80 kg = 0,88 ‰",
      ogDescription: "4 øl på 80 kg = 0,88 ‰ med Widmark-formlen. Beregn promille ud fra genstande, vægt, køn og timer — og se grænsen på 0,5 ‰.",
