      metaTitle: "Løn efter skat 2026 - Beregn din nettoløn gratis",
      metaDescription: "Beregn din nettoløn 2026. Nyt skattesystem med mellemskat og topskat. Personfradrag 54.100 kr. Se hvad du får udbetalt efter skat, AM-bidrag (8%) og pension. Gratis lønberegner.",
      keywords: ["løn efter skat", "lønberegner", "nettoløn", "beregn løn efter skat", "hvad får jeg udbetalt", "skat beregner", "bruttoløn til nettoløn", "løn 2026", "skatteberegner", "am-bidrag"],
      ogTitle: "Løn efter skat 2026 - Beregn din nettoløn",
      ogDescription: "Se hvad du får udbetalt efter skat. Gratis lønberegner med 2026 satser.",
